/* Touch gameplay layer: controls are dormant until a run starts on a touch device. */
.touch-look,.touch-controls{display:none}
@media (pointer:coarse){
 .game-ui.active .touch-look{display:block;position:absolute;inset:0;z-index:1;touch-action:none;pointer-events:auto}
 .game-ui.active .touch-controls{display:block;position:absolute;inset:0;z-index:3;pointer-events:none;padding:env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left)}
 .touch-stick{position:absolute;left:max(18px,env(safe-area-inset-left));bottom:max(22px,calc(env(safe-area-inset-bottom) + 12px));width:118px;height:118px;border:1px solid rgba(208,190,154,.25);border-radius:50%;background:rgba(5,8,7,.28);pointer-events:auto;touch-action:none;display:grid;place-items:center;}
 .stick-ring{position:absolute;inset:19px;border:1px solid rgba(208,190,154,.2);border-radius:50%;pointer-events:none}
 .stick-knob{position:absolute;width:43px;height:43px;border:1px solid rgba(215,190,145,.65);border-radius:50%;background:rgba(144,112,71,.34);box-shadow:0 0 18px rgba(0,0,0,.4);pointer-events:none;will-change:transform}
 .touch-actions{position:absolute;right:max(15px,env(safe-area-inset-right));bottom:max(19px,calc(env(safe-area-inset-bottom) + 10px));width:174px;height:178px;pointer-events:none}
 .touch-button{position:absolute;width:58px;height:58px;border:1px solid rgba(204,186,151,.48);border-radius:50%;background:rgba(8,11,9,.68);color:#e0d4bc;font:12px var(--mono);letter-spacing:.08em;box-shadow:0 4px 18px rgba(0,0,0,.32);pointer-events:auto;touch-action:manipulation;-webkit-tap-highlight-color:transparent}
 .touch-button:active,.touch-button.pressed{background:rgba(130,87,52,.72);border-color:#d0ad73;transform:scale(.96)}
 .sprint-button{right:65px;bottom:0;width:48px;height:48px;font-size:9px}
 .interact-button{right:0;bottom:45px;width:70px;height:70px;border-color:rgba(203,153,103,.78);font-size:19px}
 #touch-flashlight{right:84px;bottom:80px;width:50px;height:50px;font-size:22px}
 .small-touch-button{width:39px;height:39px;font-size:10px}
 #touch-objectives{right:48px;bottom:112px}
 #touch-pause{right:0;bottom:132px}
 .touch-hint{position:absolute;left:151px;bottom:max(28px,calc(env(safe-area-inset-bottom) + 18px));color:rgba(213,204,182,.46);font:8px var(--mono);letter-spacing:.12em;pointer-events:none}
 .objective-card{top:max(12px,env(safe-area-inset-top));left:max(12px,env(safe-area-inset-left));min-width:0;width:min(58vw,280px);padding:9px 10px;background:linear-gradient(90deg,rgba(6,9,8,.82),rgba(6,9,8,.18));}
 .objective-text{font-size:14px;margin-top:5px}.objective-progress{margin-top:6px}
 .status-left{display:none}
 .status-right{top:max(13px,env(safe-area-inset-top));right:max(13px,env(safe-area-inset-right));bottom:auto;text-align:right}
 .team-count{font-size:9px}.battery-meter{gap:6px;margin-top:7px}.battery-meter div{width:48px}
 .objective-hint{display:none}
 .objective-log{z-index:4;pointer-events:auto;padding:25px 22px;max-height:76vh;overflow:auto}
 .pause-screen,.ending-screen,.down-overlay{z-index:5}
 .interaction{z-index:2;top:calc(50% + 28px);font-size:9px}
 .toast{z-index:2;max-width:86vw;text-align:center}
 .subtitles-line{z-index:2;bottom:24%;max-width:84vw;font-size:12px}
}
@media (pointer:coarse) and (max-width:380px){.touch-stick{width:104px;height:104px}.touch-actions{transform:scale(.9);transform-origin:bottom right;right:10px}.touch-hint{left:132px;font-size:7px}.objective-card{width:55vw}.objective-progress{font-size:8px}}

