const { createRequire } = require('node:module')
const { join } = require('node:path')
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = require(join(runtime, 'linux.json'))
;(async () => {
  const browser = await chromium.launch(config.browser.launchOptions)
  const failures = []
  for (const [name, width, height] of [['phone', 390, 844], ['small-phone', 360, 740], ['desktop', 1440, 900]]) {
    const context = await browser.newContext({ viewport: { width, height }, isMobile: name !== 'desktop', hasTouch: name !== 'desktop' })
    const page = await context.newPage()
    page.on('pageerror', e => failures.push(`${name} pageerror: ${e.message}`))
    await page.goto('http://127.0.0.1:3000/?playtest', { waitUntil: 'load' })
    await page.waitForFunction(() => window.__f)
    if (name !== 'desktop') {
      await page.evaluate(() => window.__f.beginGame())
      const state = await page.evaluate(() => ({
        gameMode: window.__f.game.mode,
        touch: getComputedStyle(document.querySelector('#touch-controls')).display,
        stick: document.querySelector('#touch-stick').getBoundingClientRect().toJSON(),
        actions: document.querySelector('.touch-actions').getBoundingClientRect().toJSON(),
        objective: document.querySelector('#objective-card').getBoundingClientRect().toJSON(),
        status: document.querySelector('#status-right').getBoundingClientRect().toJSON(),
        overflow: document.documentElement.scrollWidth > innerWidth || document.documentElement.scrollHeight > innerHeight
      }))
      if (state.gameMode !== 'playing' || state.touch !== 'block' || state.overflow) failures.push(`${name}: unexpected game/control state ${JSON.stringify(state)}`)
      await page.screenshot({ path: `/tmp/opencode/${name}.png` })
      // Synthetic pointer events emulate touch; no-op capture lets the handlers be exercised headlessly.
      await page.evaluate(() => { Element.prototype.setPointerCapture = function() {} })
      const dispatch = async (selector, type, x, y, id=71) => page.locator(selector).dispatchEvent(type, { pointerId: id, pointerType: 'touch', isPrimary: true, clientX: x, clientY: y, bubbles: true })
      const stick = state.stick
      const sx = stick.x + stick.width/2, sy = stick.y + stick.height/2
      await dispatch('#touch-stick', 'pointerdown', sx + 36, sy, 71)
      const moved = await page.evaluate(() => ({ x: window.__f.player.pos.x, z: window.__f.player.pos.z }))
      await page.waitForTimeout(300)
      const movedAfter = await page.evaluate(() => ({ x: window.__f.player.pos.x, z: window.__f.player.pos.z }))
      if (movedAfter.z === moved.z && movedAfter.x === moved.x) failures.push(`${name}: stick did not move player`)
      await dispatch('#touch-stick', 'pointerup', sx + 36, sy, 71)
      const lookBefore = await page.evaluate(() => ({ yaw: window.__f.player.yaw, pitch: window.__f.player.pitch }))
      await dispatch('#touch-look', 'pointerdown', width/2, height/2, 72)
      await dispatch('#touch-look', 'pointermove', width/2 + 40, height/2 + 25, 72)
      const lookAfter = await page.evaluate(() => ({ yaw: window.__f.player.yaw, pitch: window.__f.player.pitch }))
      if (lookAfter.yaw === lookBefore.yaw || lookAfter.pitch === lookBefore.pitch) failures.push(`${name}: drag look did not update camera`)
      await dispatch('#touch-look', 'pointerup', width/2 + 40, height/2 + 25, 72)
      const flash = await page.evaluate(() => window.__f.getFlashlight().intensity)
      await page.locator('#touch-flashlight').click()
      const flashAfter = await page.evaluate(() => window.__f.getFlashlight().intensity)
      if (!(flashAfter < flash)) failures.push(`${name}: flashlight button did not toggle`)
      const paused = await page.locator('#pause-screen').evaluate(el => el.classList.contains('show'))
      await page.locator('#touch-pause').click()
      if (!(await page.locator('#pause-screen').evaluate(el => el.classList.contains('show')))) failures.push(`${name}: pause button did not open pause screen`)
      await page.locator('#touch-pause').click()
      if (await page.locator('#pause-screen').evaluate(el => el.classList.contains('show'))) failures.push(`${name}: pause button did not resume`)
      const oldObjective = await page.locator('#objective-log').evaluate(el => el.classList.contains('open'))
      await page.locator('#touch-objectives').click()
      if (await page.locator('#objective-log').evaluate(el => el.classList.contains('open')) === oldObjective) failures.push(`${name}: objectives button did not toggle`)
      await page.locator('#touch-sprint').evaluate(el => el.dispatchEvent(new PointerEvent('pointerdown', { pointerType:'touch', pointerId: 88, bubbles:true })))
      const sprintDown = await page.evaluate(() => window.__f.game.stamina)
      await page.waitForTimeout(250)
      const sprintAfter = await page.evaluate(() => window.__f.game.stamina)
      if (!(sprintAfter < sprintDown)) failures.push(`${name}: sprint did not consume stamina (movement must be active)`)
      await page.locator('#touch-sprint').evaluate(el => el.dispatchEvent(new PointerEvent('pointerup', { pointerType:'touch', pointerId:88, bubbles:true })))
      console.log(`${name} ${width}x${height}:`, JSON.stringify(state))
    } else {
      const style = await page.locator('#touch-controls').evaluate(el => getComputedStyle(el).display)
      if (style !== 'none') failures.push(`desktop: touch controls visible (${style})`)
      await page.evaluate(() => window.__f.beginGame())
      await page.keyboard.down('KeyW'); await page.waitForTimeout(250); await page.keyboard.up('KeyW')
      const desktopMoved = await page.evaluate(() => window.__f.player.pos.z < 2.4)
      if (!desktopMoved) failures.push('desktop: WASD movement failed')
      console.log('desktop: touch controls hidden; keyboard movement', desktopMoved)
    }
    await context.close()
  }
  await browser.close()
  if (failures.length) { console.error(failures.join('\n')); process.exitCode = 1 }
})().catch(e => { console.error(e); process.exitCode = 1 })
